import * as E from './engine.js';
import * as X from './exchange.js';
const app=document.getElementById('app'),modal=document.getElementById('modal'),toastNode=document.getElementById('toast');
const KEY='EPS_TOURNOIS_V1',BACKUP=KEY+'_BACKUP';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={play:'M8 5l11 7-11 7z',pause:'M8 5v14M16 5v14',plus:'M12 5v14M5 12h14',minus:'M5 12h14',back:'M19 12H5m7-7-7 7 7 7',arrow:'M5 12h14m-7-7 7 7-7 7',settings:'M4 7h16M4 17h16M9 4v6M16 14v6',trophy:'M8 3h8v8a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 15v6m-4 0h8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',tv:'M3 4h18v13H3zM12 17v4m-4 0h8',volume:'M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',close:'M6 6l12 12M18 6 6 18',person:'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 21v-2a8 8 0 0 1 16 0v2',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14m5-2 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',clock:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18m0-15v6l4 2',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',basketball:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18M3 12h18M12 3v18M5.5 5.5c8 0 13 5 13 13M5.5 18.5c0-8 5-13 13-13',football:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18m0-15 4 3-1.5 5h-5L8 9zM8 9 4 7m12 2 4-2m-5.5 7 2.5 5m-7.5-5L7 19',handball:'M15 6a3 3 0 1 0 0-6 3 3 0 0 0 0 6M3 21l7-7 4 7M6 6l6 3 6-2M12 9l-2 5 7 2M20 8a2 2 0 1 0 0-4 2 2 0 0 0 0 4',volley:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18M12 3v8l7 5M12 11l-8 4M5 6l7 5M12 11l-1 10',racket:'M14 15c4 0 8-4 8-8s-3-6-7-5-7 5-7 9 2 4 6 4M9 14l-7 8m0-3 3 3M12 5l7 7M9 9l8 5M14 2l7 7',table:'M3 5h18v11H3zM12 5v11M5 16l-2 6m16-6 2 6M3 10h18',rugby:'M4 20C-2 14 14-2 20 4s-10 22-16 16M9 9l6 6m-6-2 4-4',disc:'M12 17c6 0 10-2 10-5S18 7 12 7 2 9 2 12s4 5 10 5M5 12c4-3 10-3 14 0',hockey:'M16 2 8 19H3v3h7L20 3M16 20h5',copy:'M8 8h13v13H8zM3 16V3h13',undo:'M9 5 3 11l6 6M3 11h11a6 6 0 0 1 6 6',fullscreen:'M3 9V3h6m6 0h6v6m0 6v6h-6M9 21H3v-6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]??paths.trophy}"/></svg>`;
const btn=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const chip=(t,id)=>{const x=E.team(t,id);return `<span class="team-chip"><i class="color-dot" style="--color:${safeColor(x?.color)}"></i>${esc(x?.name)}</span>`};
const safeColor=c=>/^#[0-9a-f]{6}$/i.test(c??'')?c:'#315ae8';
function initialData(){return {schema:1,updatedAt:0,revision:0,events:[],activeId:null}}
function load(){for(const key of[KEY,BACKUP])try{const v=JSON.parse(localStorage.getItem(key));if(validData(v))return v}catch{}return initialData()}
function validData(v){return !!v&&v.schema===1&&Array.isArray(v.events)&&v.events.length<=100&&v.events.every(e=>typeof e.id==='string'&&typeof e.title==='string'&&Array.isArray(e.tournaments)&&e.tournaments.length>0&&e.tournaments.length<=20&&e.tournaments.every(t=>t&&typeof t.id==='string'&&E.SPORTS[t.config?.sport]&&E.FORMULAS[t.config?.formula]&&Array.isArray(t.teams)&&Array.isArray(t.courts)&&Array.isArray(t.rotations)&&t.rotations.length>0&&t.rotations.every(r=>Array.isArray(r.matches)&&r.matches.every(m=>Array.isArray(m.a)&&Array.isArray(m.b)&&Number.isFinite(m.scoreA)&&Number.isFinite(m.scoreB)))&&t.roundIndex>=0&&t.roundIndex<t.rotations.length))}
let data=load(),view='home',tab='courts',draft=null,draftPreview=null,findId=null,findQuery='',rankGeneral=false,role=sessionStorage.getItem('eps-role')??'teacher',refCourtId=sessionStorage.getItem('eps-ref-court'),authorized=new Set(JSON.parse(sessionStorage.getItem('eps-authorized')??'[]')),tv=new URLSearchParams(location.search).has('affichage'),zoom=Number(sessionStorage.getItem('eps-zoom')??1),installEvent=null,audioContext=null,toastTimer=null,dbPromise=null,storageWarning=false,dragMember=null,lastAudioEnd=0;
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('eps-tournois'):null;
const event=()=>data.events.find(e=>e.id===data.activeId);
const tourney=()=>event()?.tournaments.find(t=>t.id===event().selectedId)??event()?.tournaments[0];
const teacher=()=>!tv&&role==='teacher'&&(!event()?.pinHash||authorized.has(event().id));
const canScore=m=>!tv&&(teacher()||role==='referee'&&m.courtId===refCourtId||role==='student'&&event()?.studentScores);
const modes={teacher:'Enseignant',student:'Élève',referee:'Arbitre'};
function db(){if(!('indexedDB'in globalThis))return Promise.reject(Error('IndexedDB indisponible'));return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('eps-tournoi-offline',1);r.onupgradeneeded=()=>r.result.createObjectStore('snapshots');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbWrite(snapshot){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('snapshots','readwrite');tx.objectStore('snapshots').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function restoreDB(){try{const d=await db(),r=d.transaction('snapshots').objectStore('snapshots').get('current');r.onsuccess=()=>{if(validData(r.result)&&r.result.updatedAt>data.updatedAt){data=r.result;render();toast('Votre sauvegarde a été retrouvée.')}}}catch{}}
function save(){data.updatedAt=Date.now();data.revision=(data.revision??0)+1;const snapshot=JSON.stringify(data);let ok=false;try{const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(BACKUP,previous);localStorage.setItem(KEY,snapshot);ok=true}catch{try{localStorage.removeItem(BACKUP);localStorage.setItem(KEY,snapshot);ok=true}catch{}}dbWrite(structuredClone(data)).catch(()=>{if(!ok)toast('Sauvegarde impossible : exportez une copie JSON tout de suite.',true)});if(!ok&&!storageWarning){storageWarning=true;toast('Le stockage rapide est plein. Pensez à exporter une sauvegarde JSON.',true)}channel?.postMessage({type:'snapshot',data});}
function sync(v){if(validData(v)&&v.updatedAt>=data.updatedAt){data=v;render()}}
channel&&(channel.onmessage=e=>{if(e.data?.type==='snapshot')sync(e.data.data)});addEventListener('storage',e=>{if(e.key===KEY&&e.newValue)try{sync(JSON.parse(e.newValue))}catch{}});
function toast(message,persistent=false){clearTimeout(toastTimer);toastNode.textContent=message;toastNode.classList.add('show');if(!persistent)toastTimer=setTimeout(()=>toastNode.classList.remove('show'),4200)}
function dialog(title,content,footer=''){modal.innerHTML=`<div class="modal-header"><h2>${esc(title)}</h2>${btn(icon('close'),'close','icon-only','aria-label="Fermer"')}</div><div class="modal-content">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal()}
function footer(){return `<footer class="footer"><span>Tournoi EPS · Plus de jeu.</span><span>Enregistré sur cet appareil ${data.updatedAt?'· '+new Date(data.updatedAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):''}</span></footer>`}
function brand(){return btn('<span class="brand-mark">T</span> TOURNOI <em>EPS</em>','home','brand','aria-label="Accueil"')}
function topbar(){return `<header class="topbar">${brand()}<div class="top-actions"><span class="role-pill"><i class="dot-status"></i>${modes[role]??'Enseignant'}</span>${event()?btn(icon('search')+' Où je joue ?','find','small'):''}${btn(icon('person'),'roles','icon-only','aria-label="Changer de mode"')}${teacher()&&event()?btn(icon('settings'),'settings','icon-only','aria-label="Réglages du tournoi"'):''}</div></header>`}
function home(){const list=data.events.slice().reverse();return `${topbar()}<section class="hero"><div><div class="caps">Le gymnase, en un coup d’œil.</div><h1>Moins d’organisation.<br>Plus de jeu.</h1><p>Des équipes aux derniers points : vos terrains, votre chrono, vos rotations.</p>${btn(icon('plus')+' Créer un tournoi','new','lime')}${installEvent?btn('Installer l’application','install','ghost','style="color:white"'):''}</div><div class="hero-courts" aria-hidden="true">${[1,2,3,4].map(n=>`<div class="hero-court"><span>${n}</span></div>`).join('')}</div></section><div class="home-lower"><section class="panel"><div class="flex between"><h2>Vos tournois</h2>${btn(icon('upload')+' Restaurer','restore','small')}</div>${list.length?list.map(e=>{const t=e.tournaments[0];return `<div class="event-item"><div class="event-icon">${icon(E.SPORTS[t.config.sport].icon)}</div><div class="event-info"><h3>${esc(e.title)}</h3><p>${e.tournaments.length>1?'Multisport · '+e.tournaments.length+' activités':E.SPORTS[t.config.sport].name} · ${t.teams.length} équipes / joueurs · ${e.tournaments.every(t=>t.completed)?'Terminé':'En cours'}</p></div>${btn(icon('arrow'),'open-event','icon-only',`data-id="${e.id}" aria-label="Ouvrir ${esc(e.title)}"`)}</div>`}).join(''):'<div class="empty-state">Votre premier tournoi commence ici.<br>Créez-le en quelques étapes.</div>'}</section><aside class="panel"><h2>Prêt à jouer</h2><p class="muted small-text" style="margin-bottom:18px">Des exemples complets que vous pouvez modifier et utiliser.</p><div class="example-list">${btn('Basket 3×3 <span>8 équipes · 4 terrains →</span>','example','', 'data-kind="basket"')}${btn('Handball <span>6 équipes · 3 terrains →</span>','example','', 'data-kind="handball"')}${btn('Badminton <span>18 joueurs · 9 terrains →</span>','example','', 'data-kind="badminton"')}</div><details class="details"><summary>Installer sur iPad</summary><p class="small-text muted">Ouvrez l’application dans Safari, touchez Partager, puis « Sur l’écran d’accueil ». Attendez une première ouverture en ligne pour préparer l’utilisation hors connexion.</p></details></aside></div>${footer()}`}
function newDraft(){draft={step:0,title:'Tournoi EPS',selected:['basket'],multi:false,editingSport:'basket',configs:{basket:defaults('basket')},count:8,teams:E.makeTeams(8),participants:[],assignment:'balanced',pin:'',studentScores:false};draftPreview=null;view='wizard';render()}
function defaults(s){return {sport:s,format:E.SPORTS[s].formats[0][0],courtCount:s==='badminton'||s==='table'?4:3,formula:'rr',endMode:s==='basket'||s==='badminton'||s==='table'?'score':'time',duration:300,target:E.SPORTS[s].formats[0][4],sync:'common',stopPolicy:'individual',tie:'draw',overtime:60,breakSeconds:30,poolCount:2,qualifiers:2,roundCount:7,availableMinutes:0,winPoints:3,drawPoints:1,lossPoints:0,customText:''}}
function draftCfg(){return draft.configs[draft.editingSport]}
function resizeTeams(n){n=Math.max(2,Math.min(64,Math.floor(n)||2));draft.count=n;const old=draft.teams;draft.teams=Array.from({length:n},(_,i)=>old[i]??E.makeTeams(1).map(x=>({...x,name:`Équipe ${i+1}`,color:E.COLORS[i%E.COLORS.length]}))[0]);if(draft.participants.length)assignDraft();draftPreview=null}
function assignDraft(){if(draft.assignment==='existing'){const names=[...new Set(draft.participants.map(p=>p.team).filter(Boolean))];if(!names.length){draft.assignment='balanced';return assignDraft()}draft.teams=names.map((name,i)=>({id:E.uid(),name,color:draft.participants.find(p=>p.team===name&&p.color)?.color??E.COLORS[i%E.COLORS.length],members:draft.participants.filter(p=>p.team===name),level:0,active:true}));const unassigned=draft.participants.filter(p=>!p.team);unassigned.forEach((p,i)=>draft.teams[i%draft.teams.length].members.push(p));draft.count=draft.teams.length}else {draft.teams=E.balancedTeams(draft.participants,draft.count,draft.assignment);draft.count=draft.teams.length}draftPreview=null}
function field(label,name,value,type='number',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" data-field="${name}" value="${esc(value)}" ${extra}></label>`}
function select(label,name,value,options,extra=''){return `<label class="field"><span>${label}</span><select data-field="${name}" ${extra}>${options.map(([id,text])=>`<option value="${id}" ${String(value)===String(id)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`}
function wizard(){const c=draftCfg(),sport=E.SPORTS[c.sport];let body='';if(draft.step===0){body=`<div class="wizard-heading"><div class="caps muted">1 / 4 · Sport et terrains</div><h1 style="margin-top:12px">On joue à quoi ?</h1><p>Choisissez votre activité, puis les espaces disponibles.</p></div><div class="sports">${Object.entries(E.SPORTS).map(([id,s])=>btn(icon(s.icon)+esc(s.name),'sport','sport-tile '+(draft.selected.includes(id)?'selected':''),`data-id="${id}" aria-pressed="${draft.selected.includes(id)}"`)).join('')}</div><label class="check" style="margin-top:16px"><input type="checkbox" data-field="multi" ${draft.multi?'checked':''}> Tournoi multisport</label>${draft.multi&&draft.selected.length>1?select('Activité à régler','editingSport',draft.editingSport,draft.selected.map(s=>[s,E.SPORTS[s].name])):''}<div class="format-row"><h3>${esc(sport.name)} · format de pratique</h3>${sport.formats.map(f=>btn(esc(f[1]),'format','choice '+(c.format===f[0]?'selected':''),`data-id="${f[0]}" aria-pressed="${c.format===f[0]}"`)).join('')}</div><div class="two-fields" style="margin-top:24px"><div><p class="small-text" style="margin-bottom:10px">Nombre d’espaces de jeu</p><div class="stepper">${btn('−','court-minus','icon-only','aria-label="Retirer un terrain"')}<input type="number" min="1" max="24" aria-label="Nombre de terrains" data-field="courtCount" value="${c.courtCount}">${btn('+','court-plus','icon-only','aria-label="Ajouter un terrain"')}</div></div><div class="notice">${c.sport==='basket'&&c.format==='3x3'?'Un panier = un demi-terrain. Nommez ensuite chaque espace selon votre gymnase.':c.sport==='table'?'Une table = un espace de jeu.':`Format conseillé : ${sport.formats.find(f=>f[0]===c.format)?.[2]??1} joueur(s) par équipe. Les effectifs restent libres.`}</div></div><div class="court-preview">${Array.from({length:c.courtCount},(_,i)=>`<div class="mini-court">${icon('grid')} ${i+1}</div>`).join('')}</div>`}
 else if(draft.step===1){body=`<div class="wizard-heading"><div class="caps muted">2 / 4 · Participants</div><h1 style="margin-top:12px">Qui joue ?</h1><p>Nommez les équipes, ou importez vos élèves pour les répartir.</p></div><div class="flex between"><div class="stepper">${btn('−','team-minus','icon-only','aria-label="Retirer une équipe"')}<input type="number" min="2" max="64" data-field="teamCount" aria-label="Nombre d’équipes ou joueurs" value="${draft.count}">${btn('+','team-plus','icon-only','aria-label="Ajouter une équipe"')}</div><div class="import-buttons">${btn(icon('upload')+' Importer CSV / XLSX','import','small')}${btn(icon('copy')+' Coller une liste','paste','small')}</div></div>${draft.participants.length?`<div class="notice" style="margin-top:16px">${draft.participants.length} élèves importés. La répartition équilibrée utilise les niveaux et les sexes fournis.</div><div style="margin:16px 0">${select('Constitution des équipes','assignment',draft.assignment,[['balanced','Équilibrées'],['random','Aléatoires'],['existing','Équipes déjà indiquées dans la liste']])}</div>`:''}<div class="team-edit-grid" style="margin-top:22px">${draft.teams.map((t,i)=>`<div class="team-input"><input type="color" data-team-color="${i}" value="${safeColor(t.color)}" aria-label="Couleur de ${esc(t.name)}"><input type="text" data-team-name="${i}" value="${esc(t.name)}" maxlength="50" aria-label="Nom de l’équipe ${i+1}">${t.members.length?btn(`${t.members.length} élèves`,'draft-members','small',`data-index="${i}"`):''}</div>`).join('')}</div><p class="muted small-text" style="margin-top:18px">En simple, chaque équipe représente un joueur. En double, elle peut contenir deux joueurs.</p>`}
 else if(draft.step===2){body=`<div class="wizard-heading"><div class="caps muted">3 / 4 · Formule et règles</div><h1 style="margin-top:12px">Comment on joue ?</h1><p>Un format simple, les règles que vous choisissez.</p></div>${draft.multi?`<div style="margin-bottom:18px">${select('Activité','editingSport',draft.editingSport,draft.selected.map(s=>[s,E.SPORTS[s].name]))}</div>`:''}${select('Formule de tournoi','formula',c.formula,Object.entries(E.FORMULAS))}<h3 style="margin:24px 0 12px">Le match se termine…</h3><div class="choice-grid">${[['time','Au temps'],['score','Au score'],['hybrid','Score OU temps'],['free','En mode libre']].map(([v,l])=>btn(l,'end-mode','choice '+(c.endMode===v?'selected':''),`data-id="${v}" aria-pressed="${c.endMode===v}"`)).join('')}</div><div class="two-fields" style="margin-top:20px">${['time','hybrid'].includes(c.endMode)?field('Durée du match · minutes','minutes',c.duration/60,'number','min="0.25" max="120" step="0.25"'):''}${['score','hybrid'].includes(c.endMode)?field('Premier à… points / buts','target',c.target,'number','min="1" max="999"'):''}</div><div class="two-fields" style="margin-top:18px">${select('Départ des matchs','sync',c.sync,[['common','Tous les terrains ensemble'],['independent','Chaque terrain indépendant']])}${select('Arrêt des matchs','stopPolicy',c.stopPolicy,[['individual','Chaque match se termine seul'],['first','Premier match terminé = fin de rotation']])}</div><details class="details"><summary>Règles et organisation</summary><div class="stack"><div class="two-fields">${select('En cas d’égalité','tie',c.tie,[['draw','Match nul'],['golden','Point / but en or · premier à +1'],['overtime','Prolongation puis point en or']])}${field('Prolongation · secondes','overtime',c.overtime,'number','min="10" max="3600"')}</div><div class="two-fields">${field('Pause entre rotations · secondes','breakSeconds',c.breakSeconds,'number','min="0" max="600"')}${field('Temps disponible · minutes (0 = libre)','availableMinutes',c.availableMinutes,'number','min="0" max="1440"')}</div>${['pools','poolfinal','levels'].includes(c.formula)?`<div class="two-fields">${field('Nombre de poules / groupes','poolCount',c.poolCount,'number','min="1" max="8"')}${c.formula==='poolfinal'?field('Qualifiés par poule','qualifiers',c.qualifiers,'number','min="1" max="4"'):''}</div>`:''}${['swiss','ladder','king','americano'].includes(c.formula)?field('Nombre de rondes','roundCount',c.roundCount,'number','min="1" max="50"'):''}<div class="two-fields">${field('Points de classement · victoire','winPoints',c.winPoints)}${field('Points de classement · nul','drawPoints',c.drawPoints)}</div><div class="notice">En élimination, montante-descendante et King, un vainqueur est nécessaire : une égalité se joue au point / but en or. L’Americano calcule un classement individuel et change les partenaires.</div></div></details>${c.formula==='custom'?`<label class="field" style="margin-top:18px"><span>Rencontres · numéros d’équipes séparés par ;</span><textarea data-field="customText" placeholder="1;2&#10;3;4">${esc(c.customText)}</textarea></label>`:''}`}
 else{if(!draftPreview)draftPreview=buildEvent();const tournaments=draftPreview.tournaments,total=tournaments.reduce((n,t)=>n+E.allMatches(t).length,0);body=`<div class="wizard-heading"><div class="caps muted">4 / 4 · Prêt à lancer</div><h1 style="margin-top:12px">Tout est en place.</h1><p>Vérifiez, puis entrez dans votre gymnase.</p></div>${field('Nom du tournoi','title',draft.title,'text','maxlength="70"')}<div class="summary-grid"><div class="summary-box"><span>Équipes / joueurs</span><strong>${draft.count}</strong></div><div class="summary-box"><span>Activités</span><strong>${tournaments.length}</strong></div><div class="summary-box"><span>Rencontres programmées</span><strong>${total}</strong></div></div><div class="stack">${tournaments.map(t=>`<div class="notice"><strong>${E.SPORTS[t.config.sport].name} · ${esc(E.SPORTS[t.config.sport].formats.find(f=>f[0]===t.config.format)?.[1])}</strong><br>${t.courts.length} espaces · ${E.FORMULAS[t.config.formula]}<br>${ruleLabel(t)} · ${t.config.sync==='common'?'Départ commun':'Départs indépendants'}<br>${t.rotations.length} rotation(s) ${['rr','pools','levels','custom'].includes(t.config.formula)?'programmée(s)':'pour la première étape ; les suivantes dépendent des résultats'}${t.config.availableMinutes&&E.hasTime(t)?`<br>Durée prévue pour les rencontres programmées : ${Math.ceil((t.rotations.length*t.config.duration+Math.max(0,t.rotations.length-1)*t.config.breakSeconds)/60)} min ${t.rotations.length*(t.config.duration+t.config.breakSeconds)>t.config.availableMinutes*60?'· dépasse le temps disponible':''}`:''}</div>`).join('')}</div><details class="details"><summary>Accès des élèves</summary><div class="stack">${field('Code enseignant · facultatif (4 à 8 chiffres)','pin',draft.pin,'password','inputmode="numeric" minlength="4" maxlength="8" autocomplete="new-password"')}<label class="check"><input type="checkbox" data-field="studentScores" ${draft.studentScores?'checked':''}> Autoriser la saisie des scores en mode élève</label><p class="muted small-text">Les modes sont prévus pour partager cet appareil. Une TV ouverte dans le même navigateur reçoit les mises à jour. La connexion d’appareils distincts nécessite une extension réseau.</p></div></details>`}
 return `${topbar()}<div class="creation"><div class="steps" aria-label="Étape ${draft.step+1} sur 4">${[0,1,2,3].map(i=>`<div class="step ${i<=draft.step?'active':''}"></div>`).join('')}</div><div class="wizard-panel">${body}<div class="error-inline" id="wizard-error" role="alert"></div><div class="wizard-footer">${btn(icon('back')+(draft.step?' Retour':' Annuler'),'wizard-back','ghost')}${draft.step<3?btn('Continuer '+icon('arrow'),'wizard-next','primary'):btn(icon('check')+' Ouvrir les terrains','create','primary')}</div></div></div>${footer()}`}
function buildEvent(){if(!draft.teams.every(t=>t.name.trim()))throw Error('Nommez toutes les équipes.');if(new Set(draft.teams.map(t=>t.name.trim().toLowerCase())).size!==draft.teams.length)throw Error('Chaque équipe doit avoir un nom différent.');const id=E.uid();const tournaments=draft.selected.map(s=>{const c={...draft.configs[s]};if(c.formula==='custom'){c.customPairs=c.customText.trim().split(/\r?\n/).filter(Boolean).map(l=>l.split(/[;,\t]/).map(v=>Number(v.trim())-1));if(c.customPairs.some(p=>p.length!==2||p.some(x=>!Number.isInteger(x))))throw Error('Saisissez une rencontre par ligne, par exemple 1;2.')}let teams=draft.teams;if(c.formula==='americano'&&draft.selected.length>1&&draft.teams.some(x=>x.members.length>1))throw Error('En multisport, l’Americano nécessite un joueur par équipe pour conserver un classement commun.');if(c.formula==='americano'&&draft.participants.length&&draft.selected.length===1){teams=draft.participants.map((p,i)=>({id:p.id,name:[p.first,p.last].filter(Boolean).join(' '),color:E.COLORS[i%E.COLORS.length],members:[p],level:p.level,active:true}))}return E.newTournament(c,teams)});return {id,title:draft.title.trim()||'Tournoi EPS',createdAt:Date.now(),tournaments,selectedId:tournaments[0].id,pinHash:null,pinSalt:E.uid(),studentScores:draft.studentScores,audio:{enabled:true,volume:.65,sound:'buzzer',start:true,alert30:true,alert60:false,custom:null}}}
function ruleLabel(t){const c=t.config;return c.endMode==='time'?`Matchs de ${c.duration/60} min`:c.endMode==='score'?`Premier à ${c.target}`:c.endMode==='hybrid'?`${c.duration/60} min OU premier à ${c.target}`:'Fin de match libre'}
function floor(t){const f=E.SPORTS[t.config.sport].formats.find(f=>f[0]===t.config.format)?.[3]??'custom';let lines='<rect x="3" y="3" width="194" height="94" rx="2"/><path d="M100 3v94"/>';if(f==='half')lines='<rect x="3" y="3" width="194" height="94" rx="2"/><path d="M58 3v26a42 42 0 0 0 84 0V3M88 3v20h24V3"/><circle cx="100" cy="12" r="3"/><path d="M32 3v10a68 68 0 0 0 136 0V3"/>';else if(f==='basket')lines+='<circle cx="100" cy="50" r="15"/><path d="M3 30h32v40H3m194-40h-32v40h32M3 15a40 40 0 0 1 0 70m194-70a40 40 0 0 0 0 70"/>';else if(['football','rugby','ultimate','hockey','custom'].includes(f))lines+='<circle cx="100" cy="50" r="15"/><path d="M3 24h25v52H3m194-52h-25v52h25"/>';else if(f==='handball')lines+='<path d="M3 20a42 32 0 0 1 0 60m194-60a42 32 0 0 0 0 60M3 38h8v24H3m194-24h-8v24h8"/>';else lines+='<path d="M3 18h194M3 82h194M60 3v94M140 3v94M3 50h194"/>';return `<div class="court-floor" aria-hidden="true"><svg viewBox="0 0 200 100" preserveAspectRatio="none" fill="none" stroke="currentColor">${lines}</svg></div>`}
function state(m){return m.tieBreak?['tie',m.tieBreak==='golden'?'Point / but en or':'Prolongation']:m.status==='live'?['live','En cours']:m.status==='paused'?['paused','En pause']:m.status==='done'?['done',m.reason==='forfeit'?'Forfait':'Terminé']:m.status==='cancelled'?['done','Annulé']:['','À venir']}
function courtCard(t,c){const r=E.current(t),m=r.matches.find(m=>m.courtId===c.id);const editable=m&&canScore(m)&&(!E.done(m)||teacher());const [stateClass,stateText]=m?state(m):['','Libre'];return `<article class="court-card ${m&&E.done(m)?'ended':''} ${!c.available?'inactive':''}" aria-label="${esc(c.name)}"><div class="court-head"><span>${esc(c.name)}</span><span class="state ${stateClass}">${!c.available?'Indisponible':stateText}</span></div>${floor(t)}${m?`<div class="score-row">${[['a',m.a,m.scoreA],['b',m.b,m.scoreB]].map(([side,who,score])=>{const one=E.team(t,who[0]);return `<div class="score-team"><span class="team-token" style="--color:${safeColor(one?.color)}">${esc(one?.name?.slice(0,2).toUpperCase())}</span><div class="team-name">${esc(E.label(t,who))}</div>${editable&&!E.done(m)?btn(`${score}<span class="score-hint">Toucher pour +1</span>`,'score','score-button',`data-match="${m.id}" data-side="${side}" data-delta="1" aria-label="Ajouter un point à ${esc(E.label(t,who))}, score ${score}"`):`<div class="score-value">${score}</div>`}${editable&&!E.done(m)?btn('−','score','minus',`data-match="${m.id}" data-side="${side}" data-delta="-1" aria-label="Retirer un point à ${esc(E.label(t,who))}"`):''}</div>`}).join('')}</div><div class="court-foot"><span class="small-text" data-match-clock="${m.id}">${m.tieBreak==='golden'?'Prochain point gagnant':E.hasTime(t)&&m.clock?E.formatTime(E.clockLeft(m.clock)):m.status==='done'&&m.scoreA!==m.scoreB?'Gagnant : '+esc(E.label(t,m.scoreA>m.scoreB?m.a:m.b)):m.group?esc(m.group):E.hasTarget(t)?'Objectif : '+t.config.target:'Score libre'}</span>${!tv&&(teacher()||role==='referee'&&m.courtId===refCourtId)?E.done(m)?teacher()?btn('Corriger','edit-match','small',`data-match="${m.id}"`):'':m.status==='scheduled'&&t.config.sync==='independent'?btn('Démarrer','start-match','small',`data-match="${m.id}"`):btn('Terminer','finish-match','small',`data-match="${m.id}"`):''}</div>`:`<div class="empty-court"><span>${icon('grid')}</span><strong>${c.available?'Terrain libre':'Terrain indisponible'}</strong><span class="small-text">${c.available?'Aucune rencontre à cette rotation.':'Les autres terrains restent disponibles.'}</span></div>`}</article>`}
function columns(n){return n===1?1:n===2||n===4?2:n===3||n<=9?3:n<=16?4:6}
function courtGrid(t){const courts=role==='referee'&&!tv?t.courts.filter(c=>c.id===refCourtId):t.courts;const n=courts.length;return `<div class="courts-grid ${n===1?'one':n===2?'two':''} ${n>=6?'compact':''} ${n>=16||zoom<.8?'dense':''}" style="--cols:${columns(n)}">${courts.map(c=>courtCard(t,c)).join('')}</div>`}
function clockStatus(t){const r=E.current(t),complete=r.matches.every(E.done),running=r.matches.some(m=>m.status==='live'),paused=r.matches.some(m=>m.status==='paused'),remaining=E.clockLeft(r.clock);if(t.completed)return {value:'TOURNOI TERMINÉ',final:true};if(complete)return {value:'FIN DES MATCHS',final:true};if(r.matches.some(m=>m.tieBreak)&&r.clock.status==='done')return {value:'DÉPARTAGE EN COURS',final:true};if(E.hasTime(t)&&t.config.sync==='independent'){const clocks=r.matches.filter(m=>m.status==='live'&&m.clock).map(m=>E.clockLeft(m.clock));return {value:clocks.length?E.formatTime(Math.max(...clocks)):'CHRONOS INDÉPENDANTS',final:!clocks.length,remaining:clocks.length?Math.max(...clocks):remaining}}if(E.hasTime(t))return {value:E.formatTime(remaining),remaining};return {value:E.hasTarget(t)?`${t.config.target} PTS`:'JEU LIBRE',final:!E.hasTarget(t)};}
function clockBar(t){const r=E.current(t),s=clockStatus(t),finished=r.matches.filter(E.done).length,complete=finished===r.matches.length,running=r.matches.some(m=>m.status==='live'),paused=r.matches.some(m=>m.status==='paused');return `<section class="clock-bar"><div class="clock-caption"><div class="caps">${E.SPORTS[t.config.sport].name} · ${ruleLabel(t)}</div><h2>Rotation ${r.number}${['rr','pools','levels','custom'].includes(t.config.formula)?' / '+t.rotations.length:''}</h2><div class="progress-line">${finished} / ${r.matches.length} matchs terminés</div></div><div class="clock-value ${s.final?'final':''} ${s.remaining<=30000?'urgent':''}" id="main-clock">${s.value}</div>${teacher()?`<div class="clock-controls">${complete?btn(t.completed?'Voir le classement':icon('arrow')+' Rotation suivante',t.completed?'rank':'advance','lime'):running?btn(icon('pause')+' Pause générale','pause','lime'):btn(icon('play')+(paused?' Reprendre':' Lancer les matchs'),'start','lime')}${!complete?btn('Terminer','finish-all','ghost small'):''}${E.hasTime(t)&&!complete?btn('+30 s','add-time','ghost small','data-seconds="30"'):''}${btn(icon('volume'),'test-sound','ghost icon-only','aria-label="Tester le son"')}${btn(icon('settings'),'clock-settings','ghost icon-only','aria-label="Autres commandes du chrono"')}</div>`:''}</section>`}
function restStrip(t){const playing=new Set(E.current(t).matches.filter(m=>m.status!=='cancelled').flatMap(E.entrants));const rests=t.teams.filter(x=>x.active&&!playing.has(x.id));return rests.length?`<div class="rest-strip"><strong>Au repos</strong>${rests.map(x=>chip(t,x.id)).join('')}${t.engine.currentBye?'<span class="small-text">Exemption de ronde suisse : points de victoire, aucun match joué.</span>':''}</div>`:''}
function nextPanel(t){const r=E.current(t),next=t.rotations[t.roundIndex+1];if(!r.matches.every(E.done))return '';if(t.completed)return '';return `<section class="next-panel"><div class="flex between"><div><div class="caps muted">Rotation terminée</div><h2 style="margin-top:8px">${next?'La suite est prête.':'À vous la prochaine étape.'}</h2><p class="muted small-text" style="margin-top:5px">${r.matches.filter(m=>m.status==='done').length} résultats enregistrés · ${t.config.breakSeconds} s de récupération conseillée</p></div>${teacher()?btn(next?'Préparer la rotation '+next.number:'Calculer la suite','advance','primary'):''}</div>${next?`<div class="next-grid">${next.matches.map(m=>`<div class="next-item"><span class="caps muted">${esc(t.courts.find(c=>c.id===m.courtId)?.name)}</span><p>${esc(E.label(t,m.a))} / ${esc(E.label(t,m.b))}</p></div>`).join('')}</div>`:'<p class="muted small-text" style="margin-top:14px">Les adversaires suivants dépendent des résultats. En championnat, le classement final sera disponible.</p>'}</section>`}
function tournamentChrome(t){return `${topbar()}<div class="page-title"><div><div class="caps muted">${event().tournaments.length>1?'Tournoi multisport':'Votre gymnase'}</div><h1 style="margin-top:7px">${esc(event().title)}</h1></div><div class="flex">${event().tournaments.length>1?select('Activité','selectedTournament',t.id,event().tournaments.map(x=>[x.id,E.SPORTS[x.config.sport].name]),'class="sport-switch"'):''}${btn(icon('tv')+' Écran TV','tv','small')}${teacher()?btn(icon('download'),'exports','icon-only','aria-label="Exporter le tournoi"'):''}</div></div><nav class="nav-tabs" aria-label="Vues du tournoi">${btn(icon('grid')+' Terrains','courts',tab==='courts'?'selected':'')}${btn(icon('clock')+' Rotations','rotations',tab==='rotations'?'selected':'')}${btn(icon('trophy')+' Classement','rank',tab==='rank'?'selected':'')}${t.courts.length>=9&&tab==='courts'?'<label class="zoom-control nav-right">Vue compacte <input type="range" min="0.6" max="1" step="0.1" data-field="zoom" value="'+zoom+'" aria-label="Densité des terrains"></label>':''}</nav>`}
function gym(t){return clockBar(t)+courtGrid(t)+restStrip(t)+nextPanel(t)}
function rotations(t){const dynamic=!['rr','pools','levels','custom'].includes(t.config.formula),duration=t.config.duration+t.config.breakSeconds;return `<div class="notice" style="margin-bottom:18px">${E.FORMULAS[t.config.formula]} · ${E.allMatches(t).length} rencontres programmées${E.hasTime(t)?' · durée prévue : '+Math.ceil((t.rotations.length*t.config.duration+Math.max(0,t.rotations.length-1)*t.config.breakSeconds)/60)+' min':''}${dynamic?' · les tours suivants seront calculés à partir des résultats.':''}</div>${t.rotations.map((r,i)=>`<section class="rotation-card"><div class="rotation-heading ${i===t.roundIndex?'active':''}"><strong>Rotation ${r.number}${i===t.roundIndex?' · maintenant':''}</strong><span class="small-text">${E.hasTime(t)?'Début prévu : +'+E.formatTime(i*duration*1000):r.matches.length+' rencontres'}</span></div>${r.matches.map(m=>`<button class="fixture" ${teacher()?'data-action="edit-match" data-match="'+m.id+'"':'disabled'}><span class="court-label">${esc(t.courts.find(c=>c.id===m.courtId)?.name)}</span><span class="fixture-names">${esc(E.label(t,m.a))} <span class="muted">/</span> ${esc(E.label(t,m.b))}${m.phase||m.group?'<br><span class="muted small-text">'+esc([m.phase,m.group].filter(Boolean).join(' · '))+'</span>':''}</span><strong>${m.status==='scheduled'?'—':m.scoreA+' – '+m.scoreB}</strong><span class="state ${state(m)[0]}">${state(m)[1]}</span></button>`).join('')}</section>`).join('')}`}
function rankingTable(t,rows){return `<div class="table-wrap"><table class="ranking"><thead><tr><th>Rang</th><th>Équipe / joueur</th><th>Joués</th><th>V</th><th>N</th><th>D</th><th>Marqués</th><th>Diff.</th><th>${t.config.formula==='americano'?'Points individuels':'Points'}</th></tr></thead><tbody>${rows.map(s=>`<tr><td class="rank-number">${s.rank}</td><td>${chip(t,s.id)}${!s.active?' <span class="muted small-text">Absent</span>':''}</td><td>${s.played}</td><td>${s.wins}</td><td>${s.draws}</td><td>${s.losses}</td><td>${s.for}</td><td>${s.for-s.against>0?'+':''}${s.for-s.against}</td><td><strong>${t.config.formula==='americano'?s.for:s.points}</strong></td></tr>`).join('')}</tbody></table></div>`}
function ranking(t){const rows=E.standings(t);return `${t.completed&&rows[0]?`<div class="winner-banner">${icon('trophy')}<div><div class="caps">Tournoi terminé</div><h2>${esc(rows[0].name)}</h2><p>${E.eliminate(t)?'Vainqueur du tournoi':'Première place du classement'}</p></div></div>`:''}<section class="panel"><div class="flex between"><div><h2>${t.completed?'Classement final':'Classement provisoire'}</h2><p class="muted small-text" style="margin:-6px 0 20px">${t.config.formula==='americano'?'Points marqués par joueur, puis différence.':'Points : victoire '+t.config.winPoints+' · nul '+t.config.drawPoints+' · défaite '+t.config.lossPoints+'. Départage : différence, points marqués, nom.'}</p></div>${event().tournaments.length>1?btn('Général multisport','general-rank','small'):''}</div>${rankingTable(t,rows)}</section>${t.engine.groups.length?`<div class="stack" style="margin-top:20px">${t.engine.groups.map(g=>`<section class="panel"><h2>${esc(g.name)}</h2>${rankingTable(t,E.standings(t,g.ids))}</section>`).join('')}</div>`:''}`}
function generalRanking(){const rows=E.multisportStandings(event());return `<section class="panel"><div class="flex between"><h2>Classement général multisport</h2>${btn('Revenir à l’activité','rank','small')}</div><p class="muted small-text" style="margin-bottom:20px">Chaque activité terminée attribue N points au premier, puis N−1, N−2… Les activités en cours ne sont pas encore comptées.</p>${rows.length?`<div class="table-wrap"><table class="ranking"><thead><tr><th>Rang</th><th>Équipe / joueur</th><th>Activités terminées</th><th>Points</th></tr></thead><tbody>${rows.map(s=>`<tr><td class="rank-number">${s.rank}</td><td><span class="team-chip"><i class="color-dot" style="--color:${safeColor(s.color)}"></i>${esc(s.name)}</span></td><td>${s.activities}</td><td><strong>${s.points}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">Le classement général apparaîtra après la fin de la première activité.</div>'}</section>`}
function find(){const t=tourney();if(!t)return home();const team=E.team(t,findId),w=team?E.where(t,team.id):null;const list=t.teams.filter(x=>normalizedName(x).includes(X.normalized(findQuery))).slice(0,40);const now=w?.now,court=now?t.courts.find(c=>c.id===now.courtId):null;let stateText=w?.rest?'Vous êtes au repos.':now?.status==='scheduled'?'Votre prochain départ':'Vous jouez ici.';return `${topbar()}<div class="find-page"><div class="page-title"><div><div class="caps muted">Tout de suite, au bon endroit.</div><h1 style="margin-top:9px">Où je joue ?</h1></div>${btn('Voir les terrains','courts','small')}</div><label class="field lookup"><span>Votre équipe ou votre prénom</span><input type="search" data-field="findQuery" id="team-search" value="${esc(findQuery)}" placeholder="Rechercher…" autocomplete="off"></label>${team?`<div class="where-hero"><div class="caps">${esc(team.name)}</div><h2>${w.rest?'AU REPOS':esc(court?.name??'Terrain à déterminer')}</h2><p>${stateText}</p>${now&&!w.rest?`<p style="margin-top:8px">Contre ${esc(E.label(t,now.a.includes(team.id)?now.b:now.a))}</p><p class="muted" style="margin-top:10px">Rotation ${E.current(t).number} · ${state(now)[1]}</p>`:''}</div><div class="where-next"><div class="caps muted">Prochain match</div>${w.next?`<h3 style="margin-top:12px">${esc(t.courts.find(c=>c.id===w.next.courtId)?.name)} · Rotation ${w.next.number}</h3><p style="margin-top:8px">Contre ${esc(E.label(t,w.next.a.includes(team.id)?w.next.b:w.next.a))}</p>`:`<p style="margin-top:12px">${t.completed?'Votre tournoi est terminé.':['rr','pools','levels','custom'].includes(t.config.formula)?'Aucun autre match programmé.':'Les prochaines rencontres seront connues à la fin de l’étape.'}</p>`}</div>`:''}<div class="lookup-results">${list.map(x=>btn(chip(t,x.id)+`<span class="muted small-text">${esc(x.members.map(p=>p.first).filter(Boolean).join(', '))}</span>`,'find-team','',`data-id="${x.id}"`)).join('')}${!list.length?'<p class="muted">Aucune équipe trouvée.</p>':''}</div></div>${footer()}`}
function normalizedName(t){return X.normalized(t.name+' '+t.members.map(p=>p.first+' '+p.last).join(' '))}
function tvView(t){const r=E.current(t),s=clockStatus(t),next=t.rotations[t.roundIndex+1];return `<div class="tv-shell"><div class="tv-top"><div class="brand">TOURNOI EPS</div><span>${esc(event().title)} · ${E.SPORTS[t.config.sport].name}</span></div><div class="tv-clock"><div class="caps">ROTATION ${r.number}${['rr','pools','levels','custom'].includes(t.config.formula)?' / '+t.rotations.length:''} · ${ruleLabel(t)}</div><div id="main-clock" class="clock-value ${s.final?'final':''}">${s.value}</div><div class="clock-note">${r.matches.filter(E.done).length} / ${r.matches.length} matchs terminés</div></div>${courtGrid(t)}${restStrip(t)}<div class="tv-next"><strong>PROCHAINE ROTATION</strong>${next?next.matches.map(m=>`<span>${esc(t.courts.find(c=>c.id===m.courtId)?.name)} · ${esc(E.label(t,m.a))} / ${esc(E.label(t,m.b))}</span>`).join(''):'<span>Les oppositions suivantes dépendent des résultats.</span>'}</div>${btn('Quitter l’affichage','exit-tv','exit-tv small')}</div>`}
function render(){try{if(tv&&tourney()){app.innerHTML=tvView(tourney());return}let h;if(view==='wizard'&&draft)h=wizard();else if(view==='find'&&event())h=find();else if(view==='tournament'&&event()){const t=tourney();h=tournamentChrome(t)+(tab==='courts'?gym(t):tab==='rotations'?rotations(t):rankGeneral?generalRanking():ranking(t))+footer()}else h=home();app.innerHTML=`<main class="shell">${h}</main>`}catch(error){toast(error.message,true);if(view==='wizard'&&draft){draft.step=Math.min(2,draft.step);draftPreview=null;app.innerHTML=`<main class="shell">${wizard()}</main>`}}}
function openEvent(id){data.activeId=id;const e=event();if(!e)return;if(e.pinHash&&!authorized.has(id)&&role==='teacher')role='student';view='tournament';tab='courts';findId=null;save();render()}
async function digest(pin,salt){const b=new TextEncoder().encode(salt+':'+pin);return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('')}
async function create(){if(draft.pin&&!/^\d{4,8}$/.test(draft.pin))throw Error('Le code doit contenir 4 à 8 chiffres.');const e=draftPreview??buildEvent();e.title=draft.title.trim()||'Tournoi EPS';e.studentScores=draft.studentScores;if(draft.pin)e.pinHash=await digest(draft.pin,e.pinSalt);data.events.push(e);data.activeId=e.id;authorized.add(e.id);sessionStorage.setItem('eps-authorized',JSON.stringify([...authorized]));role='teacher';sessionStorage.setItem('eps-role',role);draft=null;draftPreview=null;view='tournament';tab='courts';save();render();toast('Les terrains sont prêts. Bon tournoi !')}
function showRoles(){const e=event();dialog('Quel est votre rôle ?',`<div class="role-choices">${btn(icon('settings')+' Enseignant','choose-role','', 'data-role="teacher"')}${btn(icon('person')+' Élève','choose-role','', 'data-role="student"')}${e?btn(icon('grid')+' Arbitre','choose-role','', 'data-role="referee"'):''}</div>${e?.pinHash?'<p class="muted small-text" style="margin-top:18px">Le retour au mode enseignant est protégé par votre code.</p>':'<p class="muted small-text" style="margin-top:18px">Ajoutez un code dans les réglages pour verrouiller le retour au mode enseignant.</p>'}`)}
async function chooseRole(next){if(next==='teacher'&&event()?.pinHash&&!authorized.has(event().id)){dialog('Code enseignant',`<label class="field"><span>Votre code</span><input id="teacher-pin" type="password" inputmode="numeric" maxlength="8" autocomplete="current-password"></label><div id="pin-error" class="error-inline" role="alert"></div>`,btn('Déverrouiller','unlock','primary'));return}if(next==='referee'){dialog('Quel terrain arbitrez-vous ?',`<div class="stack">${tourney().courts.map(c=>btn(esc(c.name),'choose-court','',`data-id="${c.id}"`)).join('')}</div>`);return}role=next;if(next==='student')authorized.delete(event()?.id);sessionStorage.setItem('eps-authorized',JSON.stringify([...authorized]));sessionStorage.setItem('eps-role',role);modal.close();render()}
function settings(){if(!teacher())return;const e=event(),t=tourney();dialog('Votre tournoi',`<div class="settings-grid"><section class="settings-card"><h3>Équipes et élèves</h3><p class="muted small-text" style="margin-bottom:15px">Noms, couleurs, membres et présences.</p>${btn('Gérer les équipes','teams','primary small')}</section><section class="settings-card"><h3>Terrains</h3><div class="stack">${t.courts.map(c=>`<div class="flex"><input type="text" data-court-name="${c.id}" value="${esc(c.name)}" aria-label="Nom du terrain" style="min-width:0;flex:1;padding:9px;border:1px solid #ccd8cf;border-radius:8px;width:110px"><label class="check"><input type="checkbox" data-court-available="${c.id}" ${c.available?'checked':''}> Disponible</label></div>`).join('')}</div></section><section class="settings-card"><h3>Son du gymnase</h3><div class="sound-controls"><label class="check"><input type="checkbox" data-audio="enabled" ${e.audio.enabled?'checked':''}> Activer les sons</label>${select('Signal de fin','audioSound',e.audio.sound,[['buzzer','Buzzer'],['gong','Gong'],['whistle','Sifflet'],['custom','Son personnalisé']])}<label class="field"><span>Volume · ${Math.round(e.audio.volume*100)} %</span><input type="range" data-audio="volume" min="0" max="1" step=".05" value="${e.audio.volume}"></label><label class="check"><input type="checkbox" data-audio="start" ${e.audio.start?'checked':''}> Signal de départ</label><label class="check"><input type="checkbox" data-audio="alert60" ${e.audio.alert60?'checked':''}> Alerte à une minute</label><label class="check"><input type="checkbox" data-audio="alert30" ${e.audio.alert30?'checked':''}> Alerte à 30 secondes</label>${btn(icon('volume')+' Tester le son','test-sound','small')}${btn('Choisir un fichier audio','custom-sound','small')}<p class="muted small-text">${e.audio.custom?'Son personnalisé enregistré.':'Fichier audio de 512 Ko maximum.'} Le volume final dépend aussi de l’appareil et de l’enceinte.</p></div></section><section class="settings-card"><h3>Mode élève</h3><label class="check"><input type="checkbox" data-student-scores ${e.studentScores?'checked':''}> Autoriser les scores</label><p class="muted small-text" style="margin:10px 0">Un code protège l’accès aux commandes de gestion sur cet appareil.</p>${btn(e.pinHash?'Changer le code enseignant':'Créer un code enseignant','set-pin','small')}</section><section class="settings-card"><h3>Données et exports</h3><div class="stack">${btn('Exporter XLSX / CSV / PDF','exports','small')}${btn('Sauvegarde JSON','backup','small')}${btn('Statistiques','stats','small')}</div></section><section class="settings-card"><h3>Affichage et installation</h3><p class="muted small-text" style="margin-bottom:15px">La fenêtre TV du même navigateur se met à jour automatiquement. Les autres appareils ne se synchronisent pas dans cette version locale.</p>${btn('Ouvrir la TV','tv','small')}${installEvent?btn('Installer','install','small'):''}<div style="margin-top:14px"><a href="./conception.html" target="_blank" rel="noopener">Consulter les maquettes initiales</a></div></section></div><div class="flex between" style="margin-top:22px"><span class="small-text muted">Vos données restent sur cet appareil.</span>${btn('Supprimer ce tournoi','delete-event','danger small')}</div>`)}
function teamsModal(){if(!teacher())return;const t=tourney();dialog('Les équipes',`<div class="stack">${t.teams.map(x=>`<section class="team-detail" data-drop-team="${x.id}"><div class="team-input"><input type="color" data-live-color="${x.id}" value="${safeColor(x.color)}" aria-label="Couleur de ${esc(x.name)}"><input type="text" data-live-name="${x.id}" value="${esc(x.name)}" maxlength="50" aria-label="Nom de l’équipe"><label class="check"><input type="checkbox" data-presence="${x.id}" ${x.active?'checked':''}> Présente</label></div>${x.members.map(p=>`<div class="member" draggable="true" data-drag-member="${p.id}"><span>${esc(p.first+' '+p.last)} <span class="muted">${esc(p.className)}</span></span><select data-member="${p.id}" aria-label="Déplacer ${esc(p.first)} vers une équipe">${t.teams.map(y=>`<option value="${y.id}" ${x.id===y.id?'selected':''}>${esc(y.name)}</option>`).join('')}</select></div>`).join('')}</section>`).join('')}</div><p class="muted small-text" style="margin-top:16px">Pour changer une équipe : glissez un élève ou utilisez sa liste de destination. Une absence entraîne des forfaits identifiés.</p>`)}
function draftMembers(index){const t=draft.teams[index];dialog(t.name,`<div class="stack">${t.members.map(p=>`<div class="member"><span>${esc(p.first+' '+p.last)} <span class="muted">${esc(p.className)}</span></span><select data-draft-member="${p.id}" aria-label="Équipe de ${esc(p.first)}">${draft.teams.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`).join('')}</div>`)}
function moveMember(teams,id,destination){const from=teams.find(t=>t.members.some(p=>p.id===id));if(!from||!destination||from===destination)return;const p=from.members.find(p=>p.id===id);from.members=from.members.filter(p=>p.id!==id);destination.members.push(p)}
function matchModal(id){if(!teacher())return;const t=tourney(),m=E.allMatches(t).find(x=>x.id===id);if(!m)return;dialog('Corriger une rencontre',`<p style="margin-bottom:20px"><strong>${esc(E.label(t,m.a))}</strong> / <strong>${esc(E.label(t,m.b))}</strong></p><div class="two-fields"><label class="field"><span>${esc(E.label(t,m.a))}</span><input id="edit-score-a" type="number" min="0" max="999" value="${m.scoreA}"></label><label class="field"><span>${esc(E.label(t,m.b))}</span><input id="edit-score-b" type="number" min="0" max="999" value="${m.scoreB}"></label></div><p class="muted small-text" style="margin-top:16px">Enregistrer valide ce résultat et recalcule le classement.</p>${E.current(t).matches.some(x=>x.id===id)?select('Déplacer vers un terrain libre','moveCourt',m.courtId,t.courts.filter(c=>c.available).map(c=>[c.id,c.name]),`data-match="${id}"`):''}<div id="match-error" class="error-inline" role="alert"></div>`,btn('Enregistrer le résultat','save-match','primary',`data-match="${id}"`))}
function clockSettings(){if(!teacher())return;const t=tourney();dialog('Chronométrage',`<div class="stack"><div class="notice">${ruleLabel(t)} · ${t.config.sync==='common'?'Chrono commun':'Chronos individuels'}</div><div class="flex">${btn('+30 secondes','add-time','', 'data-seconds="30"')}${btn('+1 minute','add-time','', 'data-seconds="60"')}${btn('Recommencer le chrono','reset-clock','')}</div><p class="muted small-text">Recommencer conserve les scores et remet la durée initiale. Le lancement reste manuel.</p>${btn('Terminer les matchs restants','finish-all','danger')}</div>`)}
function sheets(t){const participants=[['Nom','Prénom','Classe','Sexe','Équipe','Couleur','Niveau']],pColors=[''];for(const team of t.teams){if(!team.members.length){participants.push(['','','','',team.name,team.color,team.level]);pColors.push(team.color)}for(const p of team.members){participants.push([p.last,p.first,p.className,p.sex,team.name,team.color,p.level]);pColors.push(team.color)}}const teamRows=[['Équipe','Couleur','Membres','Présence'],...t.teams.map(x=>[x.name,x.color,x.members.map(p=>p.first+' '+p.last).join(', '),x.active?'Présente':'Absente'])];const fixtureRows=[['Rotation','Terrain','Équipe A','Équipe B','Score A','Score B','État','Phase'],...t.rotations.flatMap(r=>r.matches.map(m=>[r.number,t.courts.find(c=>c.id===m.courtId)?.name,E.label(t,m.a),E.label(t,m.b),m.scoreA,m.scoreB,state(m)[1],m.phase||m.group]))];const resultRows=[['Rang','Équipe','Joués','V','N','D','Marqués','Différence','Points'],...E.standings(t).map(x=>[x.rank,x.name,x.played,x.wins,x.draws,x.losses,x.for,x.for-x.against,t.config.formula==='americano'?x.for:x.points])];return [{name:'Participants',rows:participants,colors:pColors},{name:'Équipes',rows:teamRows,colors:['',...t.teams.map(x=>x.color)]},{name:'Terrains',rows:[['Terrain','Disponible'],...t.courts.map(c=>[c.name,c.available?'Oui':'Non'])]},{name:'Rotations et résultats',rows:fixtureRows},{name:'Classement',rows:resultRows,colors:['',...E.standings(t).map(x=>x.color)]},{name:'Horaires prévisionnels',rows:[['Rotation','Début prévu (min)','Durée (min)','Pause (s)'],...t.rotations.map((r,i)=>[r.number,E.hasTime(t)?i*(t.config.duration+t.config.breakSeconds)/60:'Selon les scores',E.hasTime(t)?t.config.duration/60:'Libre',t.config.breakSeconds])]}]}
function exportsModal(){if(!teacher())return;dialog('Exporter votre tournoi',`<p class="muted" style="margin-bottom:20px">Participants, équipes, terrains, rotations, résultats et classement.</p><div class="export-grid">${btn(icon('download')+' Excel XLSX','export-xlsx','primary')}${btn(icon('download')+' PDF','export-pdf','')}${btn(icon('download')+' CSV · classement','export-csv','', 'data-sheet="4"')}${btn(icon('download')+' CSV · rotations','export-csv','', 'data-sheet="3"')}${btn(icon('download')+' CSV · participants','export-csv','', 'data-sheet="0"')}${btn(icon('download')+' Sauvegarde JSON','backup','')}</div><p class="muted small-text" style="margin-top:20px">Le classeur Excel conserve les couleurs. Le PDF contient plusieurs sections et se télécharge directement.</p>`)}
function exportName(suffix){return event().title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9-]/g,'_').slice(0,60)+'_'+suffix}
function eventSheets(){const e=event();if(e.tournaments.length===1)return sheets(tourney());const result=e.tournaments.flatMap((t,i)=>sheets(t).map(s=>({...s,name:(i+1)+' '+E.SPORTS[t.config.sport].name.slice(0,10)+' '+s.name.slice(0,16)})));const general=E.multisportStandings(e);result.push({name:'Général multisport',rows:[['Rang','Équipe','Activités terminées','Points'],...general.map(x=>[x.rank,x.name,x.activities,x.points])],colors:['',...general.map(x=>x.color)]});return result}
function stats(){if(!teacher())return;const t=tourney(),matches=E.allMatches(t),s=E.standings(t);dialog('Statistiques',`<div class="stat-list"><div class="summary-box"><span>Rencontres terminées</span><strong>${matches.filter(m=>m.status==='done').length} / ${matches.length}</strong></div><div class="summary-box"><span>Points / buts enregistrés</span><strong>${matches.filter(m=>m.status==='done').reduce((n,m)=>n+m.scoreA+m.scoreB,0)}</strong></div><div class="summary-box"><span>Matchs joués par équipe</span><strong>${Math.min(...s.map(x=>x.played))} à ${Math.max(...s.map(x=>x.played))}</strong></div></div><div class="table-wrap" style="margin-top:18px"><table class="ranking"><thead><tr><th>Équipe</th><th>Matchs</th><th>Repos programmés</th></tr></thead><tbody>${s.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.played}</td><td>${t.rotations.filter(r=>!r.matches.some(m=>E.entrants(m).includes(x.id))).length}</td></tr>`).join('')}</tbody></table></div>`)}
async function initAudio(){const C=globalThis.AudioContext??globalThis.webkitAudioContext;if(!C)return;audioContext??=new C();if(audioContext.state==='suspended')await audioContext.resume()}
async function sound(kind='end',test=false){const settings=event()?.audio??{enabled:true,volume:.65,sound:'buzzer',start:true,alert30:true};if(!settings.enabled&&!test)return;if(!test&&(kind==='start'&&!settings.start||kind==='alert30'&&!settings.alert30||kind==='alert60'&&!settings.alert60))return;try{await initAudio();if(!audioContext){if(test)toast('Audio indisponible dans ce navigateur.');return}if(settings.sound==='custom'&&settings.custom&&kind==='end'){const b=Uint8Array.from(atob(settings.custom.split(',')[1]),c=>c.charCodeAt(0));const buffer=await audioContext.decodeAudioData(b.buffer.slice(0));const source=audioContext.createBufferSource(),gain=audioContext.createGain();source.buffer=buffer;gain.gain.value=settings.volume;source.connect(gain).connect(audioContext.destination);source.start();return}const start=audioContext.currentTime;const count=kind==='start'?3:kind.startsWith('alert')?2:settings.sound==='buzzer'?3:1;for(let i=0;i<count;i++){const osc=audioContext.createOscillator(),gain=audioContext.createGain();const when=start+i*.28;osc.type=settings.sound==='buzzer'?'square':'sine';osc.frequency.value=kind.startsWith('alert')?740:kind==='start'?520:settings.sound==='gong'?210:settings.sound==='whistle'?2400:260;const duration=kind==='end'&&settings.sound==='gong'?1.8:.2;gain.gain.setValueAtTime(.001,when);gain.gain.exponentialRampToValueAtTime(Math.max(.001,settings.volume*.25),when+.02);gain.gain.exponentialRampToValueAtTime(.001,when+duration);osc.connect(gain).connect(audioContext.destination);osc.start(when);osc.stop(when+duration+.02)}}catch{if(test)toast('Le son ne peut pas être joué. Vérifiez les réglages audio de l’appareil.')}}
function chooseFile(accept,handler){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{if(!input.files[0])return;try{await handler(input.files[0])}catch(e){toast(e.message,true)}};input.click()}
async function importParticipants(file){if(file.size>10*1024*1024)throw Error('Choisissez un fichier de moins de 10 Mo.');const rows=file.name.toLowerCase().endsWith('.xlsx')?X.readXlsx(await file.arrayBuffer()):X.parseDelimited(await file.text());applyParticipants(X.participantsFromRows(rows))}
function applyParticipants(list){if(list.length>2000)throw Error('Maximum : 2 000 participants par liste.');if(!draft)return;draft.participants=list;draft.assignment=list.some(p=>p.team)?'existing':'balanced';assignDraft();modal.close();render();toast(list.length+' participants importés.')}
function paste(){dialog('Coller une liste',`<p class="muted small-text" style="margin-bottom:15px">Copiez les cellules d’Excel ou Google Sheets, en incluant les en-têtes NOM, Prénom, Classe, Sexe, Équipe, Couleur, Niveau. Seuls NOM ou Prénom sont obligatoires.</p><label class="field"><span>Votre tableau</span><textarea id="paste-text" placeholder="NOM&#9;Prénom&#9;Classe&#9;Sexe"></textarea></label><div id="paste-error" class="error-inline" role="alert"></div>`,btn('Importer la liste','paste-submit','primary'))}
async function restoreFile(file){if(file.size>20*1024*1024)throw Error('Sauvegarde trop volumineuse.');const imported=JSON.parse(await file.text());if(!validData(imported))throw Error('Cette sauvegarde n’est pas compatible.');let count=0;for(const e of imported.events){const existing=data.events.findIndex(x=>x.id===e.id);if(existing>=0){if(!confirm('Remplacer le tournoi « '+e.title+' » par cette sauvegarde ?'))continue;data.events[existing]=e}else{data.events.push(e)}count++}data.activeId=imported.activeId;save();render();toast(count+' tournoi(s) restauré(s).')}
function requireTeacher(){if(!teacher())throw Error('Cette commande est réservée au mode enseignant.');return tourney()}
function findMatch(id){return E.allMatches(tourney()).find(m=>m.id===id)}
function tick(){const t=tourney();if(!t||view==='wizard')return;const events=E.tick(t);if(events.length){if(!tv){save();const now=Date.now();for(const type of new Set(events))if(type!=='state'&&(type!=='end'||now-lastAudioEnd>1000)){sound(type);if(type==='end')lastAudioEnd=now}}render()}const node=document.getElementById('main-clock');if(node){const s=clockStatus(t);node.textContent=s.value;node.classList.toggle('final',!!s.final);node.classList.toggle('urgent',s.remaining<=30000)}for(const m of E.current(t).matches){const n=document.querySelector(`[data-match-clock="${m.id}"]`);if(n&&m.clock&&!E.done(m))n.textContent=E.formatTime(E.clockLeft(m.clock))}}
async function action(action,node){const id=node.dataset.id;switch(action){
 case 'close':modal.close();break;
 case 'home':view='home';tv=false;render();break;
 case 'new':if(role!=='teacher')await chooseRole('teacher');if(role==='teacher')newDraft();break;
 case 'open-event':openEvent(id);break;
 case 'example':{const kind=node.dataset.kind,n=kind==='basket'?8:kind==='handball'?6:18,c=kind==='basket'?4:kind==='handball'?3:9,teams=E.makeTeams(n);if(kind==='badminton')teams.forEach((t,i)=>t.name='Joueur '+(i+1));const t=E.newTournament({...defaults(kind),courtCount:c,...(kind==='badminton'?{endMode:'time'}:{})},teams);const e={id:E.uid(),title:'Exemple · '+E.SPORTS[kind].name,createdAt:Date.now(),selectedId:t.id,tournaments:[t],pinHash:null,pinSalt:E.uid(),studentScores:false,audio:{enabled:true,volume:.65,sound:'buzzer',start:true,alert30:true,alert60:false,custom:null}};data.events.push(e);role='teacher';openEvent(e.id);break}
 case 'sport':if(!draft.multi)draft.selected=[id];else if(draft.selected.includes(id)){if(draft.selected.length>1)draft.selected=draft.selected.filter(s=>s!==id)}else draft.selected.push(id);draft.editingSport=draft.selected.includes(id)?id:draft.selected[0];draft.configs[id]??=defaults(id);draftPreview=null;render();break;
 case 'format':draftCfg().format=id;draftCfg().target=E.SPORTS[draftCfg().sport].formats.find(f=>f[0]===id)[4];draftPreview=null;render();break;
 case 'court-minus':case 'court-plus':draftCfg().courtCount=Math.max(1,Math.min(24,draftCfg().courtCount+(action==='court-plus'?1:-1)));draftPreview=null;render();break;
 case 'team-minus':case 'team-plus':resizeTeams(draft.count+(action==='team-plus'?1:-1));render();break;
 case 'wizard-back':if(draft.step===0){draft=null;view='home'}else draft.step--;render();break;
 case 'wizard-next':if(draft.step===2)draftPreview=buildEvent();draft.step++;render();scrollTo({top:0,behavior:'instant'});break;
 case 'end-mode':draftCfg().endMode=id;draftPreview=null;render();break;
 case 'create':await create();break;
 case 'draft-members':draftMembers(Number(node.dataset.index));break;
 case 'import':chooseFile('.xlsx,.csv,.tsv,.txt',importParticipants);break;
 case 'paste':paste();break;
 case 'paste-submit':try{applyParticipants(X.participantsFromRows(X.parseDelimited(document.getElementById('paste-text').value)))}catch(e){document.getElementById('paste-error').textContent=e.message}break;
 case 'courts':view='tournament';tab='courts';rankGeneral=false;render();break;
 case 'rotations':view='tournament';tab='rotations';rankGeneral=false;render();break;
 case 'rank':view='tournament';tab='rank';rankGeneral=false;render();break;
 case 'general-rank':rankGeneral=true;render();break;
 case 'find':view='find';findQuery='';render();break;
 case 'find-team':findId=id;findQuery='';render();break;
 case 'roles':showRoles();break;
 case 'choose-role':await chooseRole(node.dataset.role);break;
 case 'choose-court':role='referee';refCourtId=id;sessionStorage.setItem('eps-role',role);sessionStorage.setItem('eps-ref-court',id);view='tournament';tab='courts';modal.close();render();break;
 case 'unlock':{const e=event(),pin=document.getElementById('teacher-pin').value;if(await digest(pin,e.pinSalt)!==e.pinHash){document.getElementById('pin-error').textContent='Code incorrect.';break}authorized.add(e.id);sessionStorage.setItem('eps-authorized',JSON.stringify([...authorized]));await chooseRole('teacher');break}
 case 'settings':settings();break;
 case 'teams':teamsModal();break;
 case 'start':{const t=requireTeacher();await initAudio();E.startAll(t);save();sound('start');render();break}
 case 'pause':E.pauseAll(requireTeacher());save();render();break;
 case 'add-time':E.addTime(requireTeacher(),Number(node.dataset.seconds));save();render();toast('Temps ajouté.');break;
 case 'clock-settings':clockSettings();break;
 case 'reset-clock':{const t=requireTeacher();if(confirm('Recommencer le chrono de cette rotation ? Les scores sont conservés.')){E.resetRotation(t);save();modal.close();render()}break}
 case 'finish-all':{const t=requireTeacher();if(confirm('Terminer tous les matchs en cours avec les scores actuels ?')){E.finishAll(t);save();sound('end');modal.close();render()}break}
 case 'score':{const t=tourney(),m=findMatch(node.dataset.match);if(!m||!canScore(m)||E.done(m)&&!teacher())return;E.changeScore(t,m,node.dataset.side,Number(node.dataset.delta));if(E.done(m)){sound('end');toast(E.label(t,m.scoreA>m.scoreB?m.a:m.b)+' remporte le match.')}save();render();break}
 case 'start-match':{const t=tourney(),m=findMatch(node.dataset.match);if(!canScore(m))return;await initAudio();E.startMatch(t,m);save();render();break}
 case 'finish-match':{const t=tourney(),m=findMatch(node.dataset.match);if(!teacher()&&!(role==='referee'&&m.courtId===refCourtId))return;E.finishMatch(t,m);if(t.config.stopPolicy==='first'&&E.done(m))E.finishAll(t,'first-match');save();render();break}
 case 'advance':{const t=requireTeacher();E.advance(t);save();if(t.completed)tab='rank';render();break}
 case 'edit-match':matchModal(node.dataset.match);break;
 case 'save-match':{const t=requireTeacher();const a=Number(document.getElementById('edit-score-a').value),b=Number(document.getElementById('edit-score-b').value);try{E.correctScore(t,node.dataset.match,a,b)}catch(e){if(e.message==='RECALCUL_REQUIRED'){if(!confirm('Ce résultat modifie les tours suivants. Supprimer ces tours et recalculer la suite ?'))return;E.correctScore(t,node.dataset.match,a,b,true)}else throw e}save();modal.close();render();break}
 case 'tv':dialog('Afficher le tournoi',`<p class="muted" style="margin-bottom:20px">Branchez l’écran ou projetez cette fenêtre. Les scores suivent votre gestion dans le même navigateur.</p><div class="stack">${btn(icon('tv')+' Ouvrir une fenêtre TV','tv-window','primary')}${btn(icon('fullscreen')+' Afficher sur cet appareil','tv-here','')}</div><p class="muted small-text" style="margin-top:18px">Une autre tablette ou un autre ordinateur dispose de sa propre sauvegarde et ne reçoit pas les scores en direct.</p>`);break;
 case 'tv-window':{const url=new URL(location.href);url.searchParams.set('affichage','1');const win=window.open(url.toString(),'eps-affichage');if(!win)toast('La fenêtre est bloquée. Autorisez les fenêtres ou utilisez cet appareil.');modal.close();break}
 case 'tv-here':tv=true;modal.close();render();try{await document.documentElement.requestFullscreen()}catch{}break;
 case 'exit-tv':tv=false;if(document.fullscreenElement)await document.exitFullscreen();if(new URLSearchParams(location.search).has('affichage'))location.href=location.pathname;else render();break;
 case 'test-sound':await sound('end',true);break;
 case 'custom-sound':requireTeacher();chooseFile('audio/*',async file=>{if(file.size>512*1024)throw Error('Choisissez un son de 512 Ko maximum.');const reader=new FileReader();reader.onload=()=>{event().audio.custom=reader.result;event().audio.sound='custom';save();settings();toast('Son enregistré.')};reader.readAsDataURL(file)});break;
 case 'set-pin':requireTeacher();dialog('Code enseignant',`<label class="field"><span>Nouveau code · 4 à 8 chiffres</span><input id="new-pin" type="password" inputmode="numeric" minlength="4" maxlength="8" autocomplete="new-password"></label><p class="muted small-text" style="margin-top:15px">Ce code protège les commandes de cet appareil. Conservez-en une copie.</p>`,btn('Enregistrer le code','save-pin','primary'));break;
 case 'save-pin':{requireTeacher();const pin=document.getElementById('new-pin').value;if(!/^\d{4,8}$/.test(pin))throw Error('Saisissez 4 à 8 chiffres.');event().pinHash=await digest(pin,event().pinSalt);authorized.add(event().id);sessionStorage.setItem('eps-authorized',JSON.stringify([...authorized]));save();modal.close();toast('Code enseignant enregistré.');break}
 case 'exports':exportsModal();break;
 case 'export-xlsx':{const t=requireTeacher();const all=eventSheets();X.download(X.xlsx(all),exportName('tournoi.xlsx'),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break}
 case 'export-pdf':requireTeacher();X.download(X.pdf(eventSheets(),event().title),exportName('tournoi.pdf'),'application/pdf');break;
 case 'export-csv':requireTeacher();{const sh=sheets(tourney())[Number(node.dataset.sheet)];X.download(X.csv(sh.rows),exportName(sh.name.replaceAll(' ','_')+'.csv'),'text/csv;charset=utf-8')}break;
 case 'backup':if(event())requireTeacher();X.download(JSON.stringify(data,null,2),'Tournoi_EPS_sauvegarde.json','application/json');toast('Sauvegarde téléchargée.');break;
 case 'restore':chooseFile('.json',restoreFile);break;
 case 'stats':stats();break;
 case 'delete-event':{requireTeacher();if(confirm('Supprimer définitivement « '+event().title+' » de cet appareil ?')){data.events=data.events.filter(e=>e.id!==data.activeId);data.activeId=null;save();modal.close();view='home';render()}break}
 case 'install':if(installEvent){await installEvent.prompt();installEvent=null;render()}break;
 }}
document.addEventListener('click',async e=>{const node=e.target.closest('[data-action]');if(!node||node.disabled)return;try{await action(node.dataset.action,node)}catch(error){const where=document.getElementById('wizard-error')??document.getElementById('match-error');if(where)where.textContent=error.message;else toast(error.message,true)}});
document.addEventListener('input',e=>{const n=e.target;if(n.dataset.teamName!==undefined&&draft){draft.teams[Number(n.dataset.teamName)].name=n.value;draftPreview=null}if(n.dataset.teamColor!==undefined&&draft){draft.teams[Number(n.dataset.teamColor)].color=n.value;draftPreview=null}if(n.dataset.field==='title'&&draft)draft.title=n.value;if(n.dataset.field==='pin'&&draft)draft.pin=n.value;if(n.dataset.field==='customText'&&draft){draftCfg().customText=n.value;draftPreview=null}if(n.dataset.field==='findQuery'){const start=n.selectionStart;findQuery=n.value;findId=null;render();const input=document.getElementById('team-search');input?.focus();try{input?.setSelectionRange(start,start)}catch{}}});
document.addEventListener('change',async e=>{const n=e.target,k=n.dataset.field;try{
 if(draft&&k){if(k==='multi'){draft.multi=n.checked;if(!n.checked)draft.selected=[draft.editingSport]}else if(k==='editingSport')draft.editingSport=n.value;else if(k==='teamCount')resizeTeams(Number(n.value));else if(k==='assignment'){draft.assignment=n.value;assignDraft()}else if(k==='studentScores')draft.studentScores=n.checked;else if(!['title','pin','customText'].includes(k)){if(k==='courtCount')draftCfg().courtCount=Math.max(1,Math.min(24,Math.floor(Number(n.value)||1)));else if(k==='minutes')draftCfg().duration=Math.max(15,Math.min(7200,Number(n.value)*60||300));else draftCfg()[k]=n.type==='number'?Number(n.value):n.value}draftPreview=null;render();return}
 if(k==='selectedTournament'){event().selectedId=n.value;findId=null;refCourtId=null;save();render();return}if(k==='zoom'){zoom=Number(n.value);sessionStorage.setItem('eps-zoom',zoom);render();return}
 if(n.dataset.draftMember){moveMember(draft.teams,n.dataset.draftMember,draft.teams[Number(n.value)]);draftPreview=null;modal.close();render();return}
 if(n.dataset.audio){requireTeacher();event().audio[n.dataset.audio]=n.type==='checkbox'?n.checked:Number(n.value);save();return}if(k==='audioSound'){requireTeacher();event().audio.sound=n.value;save();return}
 if(n.hasAttribute('data-student-scores')){requireTeacher();event().studentScores=n.checked;save();return}
 if(n.dataset.presence){E.setAbsent(requireTeacher(),n.dataset.presence,!n.checked);save();render();return}
 if(n.dataset.courtName){const c=requireTeacher().courts.find(c=>c.id===n.dataset.courtName);c.name=n.value.trim()||c.name;save();render();return}
 if(n.dataset.courtAvailable){E.setCourt(requireTeacher(),n.dataset.courtAvailable,n.checked);save();render();return}
 if(n.dataset.liveName){const t=requireTeacher(),entry=E.team(t,n.dataset.liveName);if(!n.value.trim())throw Error('Le nom ne peut pas être vide.');entry.name=n.value.trim();save();render();return}
 if(n.dataset.liveColor){E.team(requireTeacher(),n.dataset.liveColor).color=n.value;save();render();return}
 if(n.dataset.member){const t=requireTeacher();moveMember(t.teams,n.dataset.member,E.team(t,n.value));save();teamsModal();render();return}
 if(k==='moveCourt'){const t=requireTeacher();E.moveMatch(t,findMatch(n.dataset.match),n.value);save();render();return}
 }catch(error){toast(error.message,true);render()}});
document.addEventListener('dragstart',e=>{const n=e.target.closest('[data-drag-member]');if(n&&teacher()){dragMember=n.dataset.dragMember;e.dataTransfer.setData('text/plain',dragMember)}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-team]')&&teacher())e.preventDefault()});document.addEventListener('drop',e=>{const n=e.target.closest('[data-drop-team]');if(n&&teacher()&&dragMember){e.preventDefault();const t=tourney();moveMember(t.teams,dragMember,E.team(t,n.dataset.dropTeam));save();teamsModal();render();dragMember=null}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;render()});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('L’utilisation hors connexion n’a pas pu être préparée.'));
addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')tick()});
setInterval(tick,250);restoreDB();render();
